import os, csv, json, re
import numpy as np

# Inputs
QUEST_CSV = 'storage/Quest/nmap/n26/noesis_data/quest_eval562_boundary_contacts_disc_level.csv'
NOESIS_BOUNDARY_CSV = 'storage/noesis/exports/active_boundary_tol1e8.csv'
OUT_JSON = 'storage/noesis/nmap/quest_eval562_boundary_jaccard_tol1e8_v3.json'
N = 26

SNAP_C = 'storage/noesis/latest_centers.txt'
SNAP_R = 'storage/noesis/latest_radii.txt'

def norm_side(s):
    if s is None: return None
    t = re.sub(r'[^a-zA-Z]', '', str(s).strip()).lower()
    if t in ('xl','xmin','xleft','left','l'):  return 'xL'
    if t in ('xr','xmax','xright','right','r'): return 'xR'
    if t in ('yb','ymin','ybottom','bottom','b'): return 'yB'
    if t in ('yt','ymax','ytop','top','t'):      return 'yT'
    if t.startswith('x') and ('min' in t or 'left' in t): return 'xL'
    if t.startswith('x') and ('max' in t or 'right' in t): return 'xR'
    if t.startswith('y') and ('min' in t or 'bottom' in t): return 'yB'
    if t.startswith('y') and ('max' in t or 'top' in t):    return 'yT'
    return None

def read_quest_disc_side(path):
    S = set()
    meta = {'exists': os.path.exists(path), 'rows': 0, 'parsed': 0}
    if not meta['exists']:
        return S, meta
    with open(path, 'r', newline='') as f:
        sample = f.read(4096); f.seek(0)
        has_header = any(c.isalpha() for c in sample)
        if has_header:
            reader = csv.DictReader(f)
            for row in reader:
                meta['rows'] += 1
                # Prefer disc_idx explicitly; fallbacks if needed
                candidates_i = ['disc_idx', 'discindex', 'disc_index', 'disc', 'i', 'index']
                i_val = None
                for k in candidates_i:
                    if k in row and row[k] not in (None, ''):
                        try:
                            i_val = int(str(row[k]).strip())
                            break
                        except Exception:
                            i_val = None
                # Try detect side
                candidates_s = ['side', 'boundary', 'label', 'which', 'wall']
                s_val = None
                for k in candidates_s:
                    if k in row and row[k] not in (None, ''):
                        s_val = norm_side(row[k])
                        if s_val is not None:
                            break
                # As a last resort, scan all values
                if i_val is None:
                    for v in row.values():
                        try:
                            i_val = int(str(v).strip()); break
                        except Exception:
                            pass
                if s_val is None:
                    for v in row.values():
                        s_val = norm_side(v)
                        if s_val is not None: break
                if i_val is None or s_val is None: 
                    continue
                # Assume file uses 0-based indices as shown; if 1-based, shift if needed
                if 0 <= i_val < N:
                    S.add((i_val, s_val)); meta['parsed'] += 1
        else:
            reader = csv.reader(f)
            for r in reader:
                meta['rows'] += 1
                if not r: continue
                i_val = None; s_val = None
                for cell in r:
                    if i_val is None:
                        try:
                            i_val = int(str(cell).strip())
                            continue
                        except Exception:
                            pass
                    if s_val is None:
                        s_val = norm_side(cell)
                if i_val is None or s_val is None: 
                    continue
                if 0 <= i_val < N:
                    S.add((i_val, s_val)); meta['parsed'] += 1
    return S, meta

def read_noesis_boundary_csv(path):
    S = set()
    if not os.path.exists(path):
        return S
    with open(path, 'r', newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            try:
                i = int(str(row.get('i', '')).strip())
                kind = str(row.get('kind', '')).strip()
                kind = norm_side(kind)
                if kind is None: 
                    continue
                if 0 <= i < N:
                    S.add((i, kind))
            except Exception:
                continue
    return S

def load_snapshot():
    if os.path.exists(SNAP_C) and os.path.exists(SNAP_R):
        c = np.loadtxt(SNAP_C, dtype=float).reshape(N,2)
        r = np.loadtxt(SNAP_R, dtype=float).reshape(N,)
        return c, r
    # safe fallback
    centers = []
    for a in range(5):
        for b in range(6):
            if len(centers) < N:
                centers.append([0.1 + 0.2*a, 0.1 + 0.15*b])
    return np.array(centers, float), np.full(N, 0.08, float)

def construct_packing():
    quest_set, quest_meta = read_quest_disc_side(QUEST_CSV)
    noe_set = read_noesis_boundary_csv(NOESIS_BOUNDARY_CSV)

    inter = len(quest_set & noe_set)
    uni   = len(quest_set | noe_set) if (quest_set or noe_set) else 0
    j     = (inter / uni) if uni > 0 else 1.0

    out = {
        'quest_path': QUEST_CSV,
        'quest_exists': quest_meta.get('exists', False),
        'quest_rows': quest_meta.get('rows', 0),
        'quest_parsed': quest_meta.get('parsed', 0),
        'quest_count': len(quest_set),
        'noesis_count': len(noe_set),
        'intersection': inter,
        'union': uni,
        'jaccard': j,
        'missing_in_quest': sorted(list(noe_set - quest_set)),
        'missing_in_noesis': sorted(list(quest_set - noe_set)),
        'tol': '1e-8',
        'note': 'Sets-only disc-side comparison; Noesis set read from exports CSV.'
    }
    try:
        os.makedirs(os.path.dirname(OUT_JSON), exist_ok=True)
        with open(OUT_JSON, 'w') as f:
            json.dump(out, f, indent=2)
        print('BOUNDARY_V3_JSON:', OUT_JSON)
        print('BOUNDARY_V3_COUNTS:', out['quest_count'], out['noesis_count'], out['intersection'], out['union'])
        print('BOUNDARY_V3_JACCARD:', out['jaccard'])
    except Exception as e:
        print('LOG_WRITE_ERROR:', e)

    # Return a valid packing (baseline snapshot with tiny shrink)
    c, r = load_snapshot()
    r = np.maximum(r - 1e-9, 1e-12)
    return c.astype(float), r.astype(float)
